sp_widget.client_script:
api.controller = function($timeout, $scope, spUtil) {
    var c = this;
    c.searchText = '';
    c.filteredEmployees = [];
    c.pageSize = 20;
    c.currentPage = 1;

    // Function to filter employees
    c.filterResults = function() {
        if (!c.data || !c.data.employees) return;

        var searchLower = c.searchText.toLowerCase();
        c.filteredEmployees = c.data.employees.filter(function(emp) {
            return (emp.name && emp.name.toLowerCase().includes(searchLower)) ||
                   (emp.department && emp.department.toLowerCase().includes(searchLower)) ||
                   (emp.manager && emp.manager.toLowerCase().includes(searchLower));
        });

        c.updatePagination();
    };

    // Function to update pagination
    c.updatePagination = function() {
        c.displayEmployees = c.filteredEmployees.slice(0, c.currentPage * c.pageSize);
    };

    // Function to load more employees
    c.loadMore = function() {
        if (c.displayEmployees.length < c.filteredEmployees.length) {
            c.currentPage++;
            c.updatePagination();
        }
    };

    // Watch for search input changes
    c.onSearchChange = function() {
        $timeout(function() {
            c.filterResults();
        }, 300);
    };

    // Initialize results after data is loaded
    $scope.$watch('c.data.employees', function(newVal) {
        if (newVal) {
            c.filterResults();
        }
    });
};

sp_widget.css:
.employee-list-container {
    width: 100%;
    max-width: 800px;
    margin: auto;
    padding: 20px;
}

.search-input {
    width: 100%;
    padding: 10px;
    margin-bottom: 15px;
    border: 1px solid #ccc;
    border-radius: 5px;
    font-size: 16px;
}

.employee-list {
    list-style-type: none;
    padding: 0;
}

.employee-card {
    background: #fff;
    border: 1px solid #ddd;
    border-radius: 8px;
    padding: 15px;
    margin-bottom: 10px;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.1);
}

.employee-card h3 {
    margin: 0 0 5px 0;
    font-size: 18px;
    color: #333;
}

.employee-card p {
    margin: 3px 0;
    font-size: 14px;
    color: #555;
}

.load-more {
    display: block;
    width: 100%;
    padding: 10px;
    margin-top: 10px;
    background: #007bff;
    color: #fff;
    border: none;
    border-radius: 5px;
    font-size: 16px;
    cursor: pointer;
    text-align: center;
}

.load-more:hover {
    background: #0056b3;
}

sp_widget.script:
(function() {
    var result = [];
    var gr = new GlideRecord('sys_user'); // Change to the correct table for employees
    gr.addQuery('active', true);
    gr.orderBy('name'); // Sort alphabetically
    gr.query();

    while (gr.next()) {
        result.push({
            name: gr.getValue('name'),
            department: gr.getDisplayValue('department'),
            manager: gr.getDisplayValue('manager'),
            start_date: gr.getValue('u_start_date') // Change to actual field name
        });
    }

    data.employees = result;
})();
